# Item Order (exploratory). Options, results and panel: jamovi/itemOrder.*.yaml
# (generated by tools/gen_yaml.py); jmvtools generates R/itemOrder.h.R. The
# statistics are in orderWiz() (R/engine-order.R). Nothing is fitted
# iteratively, so there is no Run checkbox and no cache: the analysis is
# recomputed whenever an option changes.

itemOrderClass <- if (requireNamespace("jmvcore", quietly = TRUE)) R6::R6Class(
  "itemOrderClass",
  inherit = itemOrderBase,
  private = list(
    .run = function() {
      opt <- self$options
      out <- self$results
      if (length(opt$vars) < 3L) {
        psw_jmv_todo(out$todo, c(
          "Choose at least three yes/no items (items with more answer categories are split at the midpoint of their range).",
          paste0("This looks for <b>order</b> among items, which reliability and factor analysis do not show: does endorsing one ",
                 "item imply endorsing another? The result can be a single line (a Guttman scale), a line with several ",
                 "items on the same rung, a branching order, or items that stand apart.")))
        return(invisible())
      }
      res <- tryCatch(orderWiz(self$data, opt$vars, tolerance = opt$tolerance / 100, h.min = opt$hMin),
                      error = function(e) jmvcore::reject(conditionMessage(e), code = ""))
      psw_jmv_todo(out$todo)
      info <- res$info

      out$reading$setContent(paste0(
        "<p>", paste(psw_jmv_escape(res$reading), collapse = "</p><p>"), "</p>",
        if (length(res$notes)) paste0("<ul>", paste0("<li>", psw_jmv_escape(res$notes), "</li>", collapse = ""), "</ul>") else ""))

      f <- res$fit
      psw_jmv_fill(out$fitTable, lapply(seq_len(nrow(f)), function(i) as.list(f[i, , drop = FALSE])))
      out$fitTable$setNote("what", sprintf(paste0(
        "N = %d. 'Fitting': respondents whose answers contain no exception at all. One line: everybody who endorses an ",
        "item also endorses every more common item. The order found: only the implications listed below have to hold. ",
        "When the order fits many more respondents than the line, a single line is too strict a description."),
        info$n), init = FALSE)

      it <- res$items
      psw_jmv_fill(out$itemTable, lapply(seq_len(nrow(it)), function(i)
        list(item = it$item[i], endorsed = it$endorsed[i], level = it$level[i], sameAs = it$same.as[i],
             scale = if (it$scale[i] == 0L) "unscalable" else as.character(it$scale[i]), H = it$H[i], role = it$role[i])))
      if (opt$highlight) for (i in seq_len(nrow(it)))
        if (isTRUE(it$H[i] < opt$hMin)) out$itemTable$addFormat(rowNo = i, col = "H", format = jmvcore::Cell.NEGATIVE)
      out$itemTable$setNote("what", sprintf(paste0(
        "Level: 1 = the base of the order; an item on level 3 implies items on levels 2 and 1. Scale: cumulative ",
        "(Mokken) scale the item was grouped into, bottom-up, with item H of at least %s; 'unscalable' items fit none. ",
        "H: Loevinger's scalability of the item with all the other items (1 = never an exception, 0 = unrelated)."),
        format(opt$hMin)), init = FALSE)

      if (opt$showImplications) {
        im <- res$implications
        if (is.null(im)) out$implications$setNote("none", "No implication met the two conditions.", init = FALSE)
        else psw_jmv_fill(out$implications, lapply(seq_len(nrow(im)), function(i) as.list(im[i, , drop = FALSE])))
        out$implications$setNote("what", sprintf(paste0(
          "Direct implications only (if A implies B and B implies C, A to C is not listed). An implication is accepted ",
          "when at most %s%% of those who endorse the first item do not endorse the second (Exceptions), and that is far ",
          "fewer than chance would give (H of at least %s). Items joined by = imply each other."),
          format(opt$tolerance), format(opt$hMin)), init = FALSE)
      }
      if (opt$showScales) {
        sc <- res$scales
        if (is.null(sc)) out$scales$setNote("none", "No two items reach the required H: there is no cumulative scale here.", init = FALSE)
        else psw_jmv_fill(out$scales, lapply(seq_len(nrow(sc)), function(i) as.list(sc[i, , drop = FALSE])))
        out$scales$setNote("what", paste0(
          if (length(info$unscalable)) sprintf("Unscalable: %s. ", paste(info$unscalable, collapse = ", ")) else "No item is unscalable. ",
          "Scales are built bottom-up from the pair with the highest H (after Mokken's automated item selection, without ",
          "its significance tests). H of a scale: below .30 not a scale, .30 to .40 weak, .40 to .50 medium, above strong. ",
          "A scale is a line; items on a branch can end up in the same scale as the line they branch from."), init = FALSE)
      }
      if (opt$showPatterns) {
        pt <- utils::head(res$patterns, opt$patternsN)
        yn <- function(v) ifelse(v, "yes", "no")
        psw_jmv_fill(out$patterns, lapply(seq_len(nrow(pt)), function(i)
          list(pattern = pt$pattern[i], n = pt$n[i], share = pt$share[i], line = yn(pt$line[i]), order = yn(pt$order[i]))))
        out$patterns$setNote("what", sprintf("Answers in this item order (most to least endorsed): %s. 1 = endorsed.",
                                             paste(info$order, collapse = ", ")), init = FALSE)
      }
      if (opt$showHasse) psw_jmv_plot(out$hasse, "hasse", list(h = res$hasse))
      invisible()
    },
    .diagram = function(image, ...) psw_jmv_diagram(image)
  )
)
